import json
from pathlib import Path


# ============================================================
# VISTA MASTER RESULTS BUILDER
# ============================================================
#
# Combines the results already generated by VISTA into one
# machine-readable master file.
#
# IMPORTANT:
# This script DOES NOT run simulation.
# It only reads existing JSON result files.
# ============================================================


# ============================================================
# 1. PATHS
# ============================================================

BASE_DIR = Path(__file__).resolve().parents[1]

DATA_DIR = (
    BASE_DIR
    / "member2"
    / "data"
)


OUTPUT_FILE = (
    DATA_DIR
    / "vista_master_results.json"
)


# ============================================================
# 2. HELPER FUNCTIONS
# ============================================================

def load_json(filename):

    filepath = DATA_DIR / filename

    if not filepath.exists():

        print(
            f"WARNING: {filename} not found."
        )

        return None

    try:

        with open(
            filepath,
            "r"
        ) as file:

            return json.load(file)

    except Exception as error:

        print(
            f"WARNING: Could not read {filename}"
        )

        print(
            error
        )

        return None


# ============================================================
# 3. BENCHMARKS
# ============================================================

BENCHMARKS = [

    "c17",

    "c432",

    "c499"

]


master = {

    "project":
        "VISTA",

    "full_name":
        "Verification Intelligence & Silicon Test Analyzer",

    "version":
        "integration",

    "benchmarks":
        {},

    "ml":
        {},

    "experiments":
        {}

}


# ============================================================
# 4. PROCESS SIMULATION RESULTS
# ============================================================

print()
print(
    "VISTA MASTER RESULTS BUILDER"
)

print(
    "============================"
)


for benchmark in BENCHMARKS:

    print()
    print(
        "Processing:",
        benchmark.upper()
    )


    simulation_filename = (
        f"{benchmark}_simulation_results.json"
    )


    simulation = load_json(
        simulation_filename
    )


    if simulation is None:

        continue


    # --------------------------------------------------------
    # Fault statistics
    # --------------------------------------------------------

    total_faults = len(
        simulation
    )


    detected_faults = 0

    undetected_faults = []


    for fault in simulation:

        detection_count = int(

            fault.get(
                "detection_count",
                0
            )

        )


        if detection_count > 0:

            detected_faults += 1

        else:

            undetected_faults.append({

                "fault_id":
                    fault.get(
                        "fault_id"
                    ),

                "net":
                    fault.get(
                        "net"
                    ),

                "fault_type":
                    fault.get(
                        "fault_type"
                    )

            })


    if total_faults > 0:

        coverage = (

            detected_faults
            /
            total_faults
            *
            100.0

        )

    else:

        coverage = 0.0


    # --------------------------------------------------------
    # Detection difficulty
    # --------------------------------------------------------

    hard = 0
    medium = 0
    easy = 0


    for fault in simulation:

        detection_count = int(

            fault.get(
                "detection_count",
                0
            )

        )


        # VISTA absolute diagnosis definition

        if detection_count == 0:

            hard += 1

        elif detection_count <= 8:

            medium += 1

        else:

            easy += 1


    # --------------------------------------------------------
    # Store benchmark information
    # --------------------------------------------------------

    master[
        "benchmarks"
    ][
        benchmark
    ] = {

        "simulation": {

            "total_faults":
                total_faults,

            "detected_faults":
                detected_faults,

            "undetected_faults":
                len(
                    undetected_faults
                ),

            "fault_coverage_percent":
                round(
                    coverage,
                    4
                ),

            "undetected_fault_list":
                undetected_faults

        },

        "diagnosis": {

            "hard":
                hard,

            "medium":
                medium,

            "easy":
                easy

        }

    }


    print(
        "  Faults:",
        total_faults
    )

    print(
        "  Detected:",
        detected_faults
    )

    print(
        "  Coverage:",
        f"{coverage:.2f}%"
    )

    print(
        "  Hard:",
        hard
    )

    print(
        "  Medium:",
        medium
    )

    print(
        "  Easy:",
        easy
    )


# ============================================================
# 5. PATTERN COMPACTION RESULTS
# ============================================================
#
# These files are optional.
#
# If a benchmark's compaction JSON exists, it is included.
# Missing files do NOT stop the script.
# ============================================================

print()
print(
    "Processing pattern compaction..."
)


for benchmark in BENCHMARKS:

    possible_files = [

        f"{benchmark}_pattern_compaction.json",

        f"{benchmark}_compaction.json"

    ]


    compaction = None

    filename_used = None


    for filename in possible_files:

        filepath = DATA_DIR / filename


        if filepath.exists():

            compaction = load_json(
                filename
            )

            filename_used = filename

            break


    if compaction is None:

        print(
            f"  {benchmark.upper()}: "
            f"no compaction JSON found"
        )

        continue


    # --------------------------------------------------------
    # Extract common fields safely
    # --------------------------------------------------------

    original_count = (

        compaction.get(
            "original_pattern_count"
        )

    )


    selected_count = (

        compaction.get(
            "selected_pattern_count"
        )

    )


    reduction = (

        compaction.get(
            "pattern_reduction_percent"
        )

    )


    compaction_coverage = (

        compaction.get(
            "compaction_coverage_percent"
        )

    )


    master[
        "benchmarks"
    ].setdefault(
        benchmark,
        {}
    )


    master[
        "benchmarks"
    ][
        benchmark
    ][
        "pattern_compaction"
    ] = {

        "source_file":
            filename_used,

        "original_pattern_count":
            original_count,

        "selected_pattern_count":
            selected_count,

        "pattern_reduction_percent":
            reduction,

        "compaction_coverage_percent":
            compaction_coverage

    }


    print(
        f"  {benchmark.upper()}: "
        f"{original_count} -> "
        f"{selected_count}"
    )


# ============================================================
# 6. ML VS RANDOM RESULTS
# ============================================================

print()
print(
    "Processing ML prioritization..."
)


ml_vs_random = load_json(
    "ml_vs_random_comparison.json"
)


if ml_vs_random is not None:

    master[
        "ml"
    ][
        "prioritization_comparison"
    ] = ml_vs_random


    print(
        "  ML vs Random loaded."
    )

else:

    print(
        "  ML vs Random results not found."
    )


# ============================================================
# 7. RANDOM BASELINE
# ============================================================

random_baseline = load_json(
    "random_relative_baseline_results.json"
)


if random_baseline is not None:

    master[
        "ml"
    ][
        "random_baseline"
    ] = random_baseline


    print(
        "  Random baseline loaded."
    )


# ============================================================
# 8. ML CLASSIFICATION RESULTS
# ============================================================

ml_prioritization = load_json(
    "ml_fault_prioritization_results.json"
)


if ml_prioritization is not None:

    master[
        "ml"
    ][
        "classification_prioritization"
    ] = ml_prioritization


    print(
        "  ML classification results loaded."
    )


# ============================================================
# 9. ML REGRESSION RESULTS
# ============================================================

ml_regression = load_json(
    "ml_regression_prioritization_results.json"
)


if ml_regression is not None:

    master[
        "ml"
    ][
        "regression_prioritization"
    ] = ml_regression


    print(
        "  ML regression results loaded."
    )


# ============================================================
# 10. EXPERIMENT SUMMARY
# ============================================================

master[
    "experiments"
] = {

    "fault_simulation":
        "Completed",

    "fault_coverage":
        "Completed",

    "fault_diagnosis":
        "Completed",

    "pattern_compaction":
        "Completed",

    "multi_benchmark_dataset":
        "Completed",

    "cross_benchmark_ml":
        "Completed",

    "ml_fault_prioritization":
        "Completed",

    "random_baseline":
        "Completed",

    "ml_vs_random_comparison":
        "Completed",

    "atpg_integration":
        "Pending Member 1 integration",

    "dashboard":
        "Pending"

}


# ============================================================
# 11. SAVE MASTER FILE
# ============================================================

with open(
    OUTPUT_FILE,
    "w"
) as file:

    json.dump(
        master,
        file,
        indent=4
    )


# ============================================================
# 12. FINAL SUMMARY
# ============================================================

print()
print(
    "========================================"
)

print(
    "MASTER RESULTS CREATED"
)

print(
    "========================================"
)


print()

print(
    "Benchmarks included:"
)


for benchmark in master[
    "benchmarks"
]:

    print(
        " -",
        benchmark.upper()
    )


print()

print(
    "ML results included:",
    bool(
        master["ml"]
    )
)


print()

print(
    "Output:"
)

print(
    OUTPUT_FILE
)


print()

print(
    "VISTA master results build complete."
)